  Proof.
    intros z Hz. unfold PropExec.seg_rom, memory_read. rewrite wa_unsigned by lia. change (Z.of_N 1) with 1.
    replace (find_segment ASEGS z 1) with (Some Asan_segment_003).
    2:{ rewrite asan_segs_eq. cbn -[Z.leb Z.add Z.of_N]. cbn [Z.of_N seg_base seg_size Asan_segment_000 Asan_segment_001 Asan_segment_002 Asan_segment_003].
