  (* rc.2: depot.py's rehash puts t0's bucket (287994) below t1's (726378); the cases follow that order. *)
  intros b Hb. change (Z.pow 2 20) with 1048576 in Hb.
  pose proof dp_tab_zero4 as Z4. pose proof dp_tab_slots as [S0 S1].
  unfold depot0, pm_trace_hash; cbn [AsDepotInv.d_chain].
  destruct (AsMainSyms.pm_short (bv_unsigned sp0)) eqn:PS; cbv beta iota in S0, S1.
  - replace (AsDepotInv.bucket 0x8ca5c831465b156a) with 726378 by (vm_compute; reflexivity).
    destruct (Z.eqb_spec b 726378) as [->|N1]; cbn [hd].
    + replace (0x2a2118 + 4 * 726378) with 0x5676c0 by lia. exact S0.
    + destruct (Z.eqb_spec b 287994) as [->|N0].
      * replace (0x2a2118 + 4 * 287994) with 0x3bb500 by lia. exact S1.
      * apply Z4. lia.
  - replace (AsDepotInv.bucket 0xfe40405393b464fa) with 287994 by (vm_compute; reflexivity).
    destruct (Z.eqb_spec b 287994) as [->|N0]; cbn [hd].
    + replace (0x2a2118 + 4 * 287994) with 0x3bb500 by lia. exact S1.
    + destruct (Z.eqb_spec b 726378) as [->|N1].
      * replace (0x2a2118 + 4 * 726378) with 0x5676c0 by lia. exact S0.
      * apply Z4. lia.
Qed.

